def controls(label): return f'<div class="ah-rail-controls" aria-label="{label}"><div class="ah-scroll-cue"><span>Faites défiler <span aria-hidden="true">↔</span></span><div class="ah-scroll-track" aria-hidden="true"><span data-scroll-progress></span></div></div><button class="ah-arrow" type="button" data-prev aria-label="Précédent">{arrow("prev")}</button><button class="ah-arrow" type="button" data-next aria-label="Suivant">{arrow("next")}</button></div>'
def rail_script(mount): return '''<script>(()=>{const r=document.getElementById('wix-bridge-section-MOUNT'),v=r?.querySelector('[data-rail]'),p=r?.querySelector('[data-prev]'),n=r?.querySelector('[data-next]');if(!v||!p||!n)return;const motion=matchMedia('(prefers-reduced-motion:reduce)').matches?'auto':'smooth';const update=()=>{const max=Math.max(0,v.scrollWidth-v.clientWidth),progress=r.querySelector('[data-scroll-progress]');p.disabled=v.scrollLeft<4;n.disabled=v.scrollLeft+v.clientWidth>=v.scrollWidth-4;if(progress){const fraction=Math.min(1,v.clientWidth/v.scrollWidth);progress.style.width=(fraction*100)+'%';progress.style.transform='translateX('+(max?Math.max(0,Math.min(max,v.scrollLeft))/max*(1-fraction)/fraction*100:0)+'%)';progress.parentElement.parentElement.hidden=max<4}};const step=()=>v.firstElementChild.getBoundingClientRect().width+parseFloat(getComputedStyle(v).columnGap);p.onclick=()=>v.scrollBy({left:-step(),behavior:motion});n.onclick=()=>v.scrollBy({left:step(),behavior:motion});v.addEventListener('scroll',update,{passive:true});new ResizeObserver(update).observe(v);update()})();</script>'''.replace('MOUNT',mount)
modules=[]
def write(file,mount,order,content,css='',script=''):
    accents={
      'navbar': 'SCOPE .ah-wordmark{color:#87475b}SCOPE .ah-nav{border-bottom:1px solid #eadde0}SCOPE .ah-project-link span{color:#647b92}SCOPE .ah-desktop-nav a{position:relative}SCOPE .ah-desktop-nav a:after{content:"";position:absolute;left:0;bottom:3px;width:18px;height:2px;background:#b9808e;transition:width .3s cubic-bezier(.2,.7,.2,1)}SCOPE .ah-desktop-nav a:nth-child(even):after{background:#8296aa}SCOPE .ah-desktop-nav a:hover:after{width:100%}SCOPE .ah-mobile-menu summary{color:#87475b}',
      'hero': 'SCOPE .ah-eyebrow{color:#87475b}SCOPE .ah-hero-copy .ah-cta{background:#87475b}SCOPE .ah-hero-copy .ah-cta:hover{background:#713c4d}SCOPE .ah-hero-controls{color:#87475b}SCOPE .ah-hero-note:before{content:"";display:inline-block;width:19px;height:1px;background:#8296aa;vertical-align:middle;margin-right:10px}',
      'introduction': 'SCOPE .ah-intro:before{content:"";display:block;width:34px;height:2px;background:#b9808e;margin:0 auto 30px}SCOPE .ah-eyebrow{color:#87475b}',
      'categories': 'SCOPE .ah-icon-categories a:nth-child(odd) svg{color:#94576a}SCOPE .ah-icon-categories a:nth-child(even) svg{color:#647b92}',
      'collections': 'SCOPE .ah-eyebrow{color:#87475b}SCOPE .ah-rail-controls button:not(:disabled){color:#87475b}',
      'engagements': 'SCOPE .ah-commitments article:nth-child(odd) svg{color:#94576a}SCOPE .ah-commitments article:nth-child(even) svg{color:#647b92}'
    }
    if mount in ('collections','boutique'):
        css+='SCOPE .ah-scroller{grid-auto-columns:calc((100% - 112px)/4.5);gap:28px}SCOPE .ah-card h3{font-size:18px;margin-top:18px}SCOPE .ah-card p{font-size:12px}SCOPE .ah-collection-image{aspect-ratio:1.08}SCOPE .ah-product-photo{aspect-ratio:1}SCOPE .ah-card .ah-link{font-size:9px}@media(min-width:701px) and (max-width:1000px){SCOPE .ah-scroller{grid-auto-columns:calc((100% - 66px)/3.5);gap:22px}}@media(max-width:700px){SCOPE .ah-scroller{grid-auto-columns:58%;gap:16px}SCOPE .ah-card h3{font-size:17px}SCOPE .ah-card p{font-size:11px}}'
        css+='SCOPE .ah-scroll-cue{margin-right:auto;display:flex;align-items:center;gap:24px;color:#87475b}SCOPE .ah-scroll-cue>span{font-size:10px;letter-spacing:.08em;white-space:nowrap}SCOPE .ah-scroll-cue>span>span{margin-left:10px;font-size:16px}SCOPE .ah-scroll-track{width:clamp(90px,17vw,240px);height:2px;background:#eadde0;overflow:hidden}SCOPE .ah-scroll-track>span{display:block;height:100%;background:#94576a;transform-origin:left}SCOPE .ah-scroll-cue[hidden]{display:none}@media(max-width:700px){SCOPE .ah-scroll-cue{gap:12px}SCOPE .ah-scroll-track{width:65px}SCOPE .ah-scroll-cue>span{font-size:9px}SCOPE .ah-rail-controls{gap:6px}}'
    css+=accents.get(mount,'')
    scope='#wix-bridge-section-'+mount
    text='<style>'+font+base.replace('SCOPE',scope)+css.replace('SCOPE',scope)+'</style>\n'+content+'\n'+script
    (root/file).write_text(text)
    modules.append(dict(file=str(root/file),mountId=mount,mountOrder=order))
